import {validateMessage} from './validation.js';

// @spec specs/hal-engine-conversation-list/spec.md#32
it('validates list_sessions paging and strips fields outside the authenticated request', () => {
  expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
  for (const updatedAt of ['2026-10-01T00:00:00.000Z', 0]) {
    const before = {sessionId: 's'.repeat(128), updatedAt};
    expect(validateMessage({type: 'list_sessions', limit: 0, before, userId: 'other'})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 0, before},
    });
  }
  expect(validateMessage({type: 'list_sessions', limit: 201})).toEqual({
    valid: true,
    data: {type: 'list_sessions', limit: 201},
  });
  for (const limit of [-1, 1.5, '10', null, NaN, Infinity]) {
    expect(validateMessage({type: 'list_sessions', limit})).toEqual({
      valid: false,
      error: expect.stringContaining('limit'),
    });
  }
  for (const before of [null, [], 'date', {}, {sessionId: '', updatedAt: 0},
    {sessionId: 's'.repeat(129), updatedAt: 0}, {sessionId: 's', updatedAt: 'not a date'},
    {sessionId: 's', updatedAt: Infinity}, {sessionId: 's', updatedAt: null}]) {
    expect(validateMessage({type: 'list_sessions', before})).toEqual({
      valid: false,
      error: expect.stringContaining('before'),
    });
  }
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/transport/ws/listSessionsValidation.test.ts"

